-- Incident location on FIRs, and the Kolkata gazetteer behind location suggestions.
--
-- Suggestions come from this table, never from an external geocoding service,
-- so an incident address typed into an FIR does not leave the platform. The
-- gazetteer is an offline OpenStreetMap extract (ODbL): names and approximate
-- points of localities, roads, landmarks, police stations, rail and metro
-- stations, and PIN codes. © OpenStreetMap contributors, available under the
-- Open Database Licence (https://www.openstreetmap.org/copyright). An SP or
-- above adds a missing place as an officer row (audited through the API).

ALTER TABLE firs ADD COLUMN IF NOT EXISTS incident_latitude DOUBLE PRECISION;
ALTER TABLE firs ADD COLUMN IF NOT EXISTS incident_longitude DOUBLE PRECISION;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fir_incident_point_paired') THEN
        ALTER TABLE firs ADD CONSTRAINT fir_incident_point_paired
            CHECK ((incident_latitude IS NULL) = (incident_longitude IS NULL));
    END IF;
    -- West Bengal's extent: a point outside it is a mistake, not an incident.
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fir_incident_point_in_west_bengal') THEN
        ALTER TABLE firs ADD CONSTRAINT fir_incident_point_in_west_bengal
            CHECK (incident_latitude IS NULL OR (incident_latitude BETWEEN 21.4 AND 27.3 AND incident_longitude BETWEEN 85.8 AND 89.9));
    END IF;
END $$;

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS gazetteer_places (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    kind            VARCHAR(16)  NOT NULL CHECK (kind IN ('locality', 'road', 'landmark', 'police_station', 'rail_station', 'metro_station', 'pin_code')),
    name            VARCHAR(200) NOT NULL CHECK (length(trim(name)) >= 2),
    name_bn         VARCHAR(200),
    pin             VARCHAR(6)   CHECK (pin IS NULL OR pin ~ '^7[0-4][0-9]{4}$'),
    latitude        DOUBLE PRECISION NOT NULL CHECK (latitude BETWEEN 21.4 AND 27.3),
    longitude       DOUBLE PRECISION NOT NULL CHECK (longitude BETWEEN 85.8 AND 89.9),
    source          VARCHAR(12)  NOT NULL CHECK (source IN ('osm', 'officer')),
    status          VARCHAR(10)  NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'pending', 'rejected', 'retired')),
    note            TEXT,
    decision_reason TEXT,
    created_by      UUID REFERENCES users(id) ON DELETE SET NULL,
    decided_by      UUID REFERENCES users(id) ON DELETE SET NULL,
    decided_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT gazetteer_osm_rows_active CHECK (source = 'officer' OR status = 'active'),
    CONSTRAINT gazetteer_decision_complete CHECK ((decided_by IS NULL) = (decided_at IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_gazetteer_osm ON gazetteer_places (kind, lower(name), round(latitude::numeric, 4), round(longitude::numeric, 4)) WHERE source = 'osm';
CREATE INDEX IF NOT EXISTS idx_gazetteer_name_trgm ON gazetteer_places USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_gazetteer_status ON gazetteer_places (status, kind);

-- OpenStreetMap rows are imported reference data and are not editable.
CREATE OR REPLACE FUNCTION gazetteer_osm_readonly() RETURNS trigger AS $$
BEGIN
    IF OLD.source = 'osm' THEN
        RAISE EXCEPTION 'imported gazetteer rows are read-only' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS gazetteer_osm_readonly ON gazetteer_places;
CREATE TRIGGER gazetteer_osm_readonly BEFORE UPDATE OR DELETE ON gazetteer_places
    FOR EACH ROW EXECUTE FUNCTION gazetteer_osm_readonly();


